// === Tab: mySketch ===
var particles = []

function setup() {
	createCanvas(960, 720)
	// noLoop() removed for animationcolorMode(RGB, 255, 255, 255, 100);
	noStroke()
	setBackground()
	rectMode(CENTER)

}

function setBackground() {
	let diskSampling = new PoissonDiskSampling({
		shape: [width*1.4, height*1.4],
		minDistance: 12,
		maxDistance: 12,
		tries: 40
	})
	let samplings = diskSampling.fill()
	for(let pos of samplings) {
		let vec = createVector(pos[0] - width*0.2, pos[1] - height*0.2)
		let col = lerpColor(color('#94B9E0'), color('#DDE8ED'), vec.y/height + random(-0.15, 0.15))
		col.setAlpha(40)
		fill(col)
		rect(vec.x, vec.y, 60, 35)
	}
}

function draw() {
	let cloudPoses = []
	// cloudPosesに雲を描く座標を登録する
	for(let i = 0; i < 30; i++) {
		let x = width * random()
		let y = height*0.85 * (1 - pow(random(), 3))
		cloudPoses.push([x, y])
	}
	// cloudPosesをy座標が大きい順に並び替える
	cloudPoses.sort(function(a,b){
        if( a[1] > b[1] ) return -1;
        if( a[1] < b[1] ) return 1;
        return 0;
	})

	for(let pos of cloudPoses) {
		let yRatio = (height*0.85 - pos[1]) / (height*0.85)
		let baseSize = 400 * pow(yRatio, 0.5)
		let cloudWidth = baseSize * random(1.3, 1.6)
		let cloudHeight = baseSize * random(0.5, 0.7)
		fractualCloud(pos[0], pos[1], cloudWidth, cloudHeight, [0, 1], 0, ceil(4 * pow(yRatio, 0.2)))
	}


	for (let particle of particles) {
		fill(particle.col)
		rect(particle.x, particle.y, particle.width, particle.height)
	}
}

function keyPressed() {
	saveCanvas('cloudForm', 'png')
}

function fractualCloud(_x, _y, _width, _height, _colRange, _depth, _maxDepth) {
	/* 規程の深さまで再帰する */
	if(_depth < _maxDepth) {
		const childrenNum = floor(random(6, 9))
		for(let i = 0; i < childrenNum; i++) {
			let childRelPos = distributeInDia(_width, _height)
			let avgSize = (_width + _height) / 2
			let childWidth = _width * random(0.5, 0.7)
			let childHeight = _height * random(0.5, 0.7)

			let nextColRangeWidth = 0.7 * (_colRange[1] - _colRange[0])
			let nextColMedian = _colRange[0] + (_colRange[1] - _colRange[0]) * (childRelPos[1] + _height/2) / _height
			let nextColRange = [ max(0, nextColMedian - nextColRangeWidth/2), min(1, nextColMedian + nextColRangeWidth/2) ]
			fractualCloud(_x + childRelPos[0], _y + childRelPos[1], childWidth, childHeight, nextColRange, _depth+1, _maxDepth)
		}
	} else {
		const particlesNum = 10
		for(let i = 0; i < particlesNum; i++) {
			let particleRelPos = distributeInDia(_width, _height)
			var avgSize = (_width + _height) / 2
			let particleWidth = avgSize * random(0.2, 0.8)
			let particleHeight = avgSize * random(0.2, 0.8)
			var col = lerpColor(color('#F2ECEB'), color('#595951'), pow(sin(HALF_PI * random(_colRange[0], _colRange[1])), 9/_depth))
			col.setAlpha(random(3, 7) * sq(_depth/4))
			makeParticle(_x + particleRelPos[0], _y + particleRelPos[1], particleWidth, particleHeight, col)
		}
	}
}

function makeParticle(_x, _y, _width, _height, _col) {
	particles.push({
		x: _x,
		y: _y,
		width: _width,
		height: _height,
		col: _col
	})
}

/* ひし形の内部の点をランダムに１つ選ぶ */
function distributeInDia(_width, _height) {
	let pos = [random(-1, 1), random(-1, 1)]

	if(pos[0] + pos[1] > 1) {
		pos[0]--
		pos[1]--
	} else if(pos[0] + pos[1] < -1) {
		pos[0]++
		pos[1]++
	} else if(-pos[0] + pos[1] > 1) {
		pos[0]++
		pos[1]--
	} else if(pos[0] - pos[1] > 1) {
		pos[0]--
		pos[1]++
	}
	pos[0] *= _width/2
	pos[1] *= _height/2

	return pos
}
